{
  "comments": [
    {
      "number": 1,
      "title": "Separate disagreement sampling from confidence based verification",
      "quote": "Disagreements may be especially likely to attract scrutiny, and people may preferentially check disagreements when they feel confident in their own answer. The resulting feedback can answer a different question from the one used to decide whether to adopt the advisor.",
      "feedback": "These sentences place two kinds of selection under one warning, leaving it unclear which can mislead a global comparison. The paper’s paired accuracy result draws an important distinction: on agreements, the two sources have identical correctness, so sampling disagreements uniformly preserves the sign of their overall accuracy difference. Checking some disagreements more often according to confidence can change that sign in the verified sample. Add “Uniformly sampled disagreements still preserve the direction of the paired accuracy difference; confidence-dependent checking need not” after the first quoted sentence to make the distinction clear.",
      "status": "Pending",
      "severity": "minor",
      "confidence": "high"
    }
  ]
}

